function atlas.lootFrequency(mount)
    local accountSource = atlas.accountLootSources and atlas.accountLootSources[mount.id]
    if accountSource then return accountSource.frequency end
    local worldBoss = atlas.worldBossLocks and atlas.worldBossLocks[mount.id]
    if worldBoss then return worldBoss.frequency end
    local explicit = atlas.lootFrequencies[mount.id]
    if explicit then return explicit end
    if (mount.isRaid or mount.kind == "Рейд") and (mount.kind == "Рейд" or mount.kind == "Добыча") then
        return "weekly"
    end
end

