-- Display-only reward lookup. The original lootItems table still owns drop
-- denominators and prerequisite/container semantics used by the counters.
function atlas.rewardItem(mount, location, includeTeachingItem)
    if mount and atlas.vendorTokenSource then
        local _, offer = atlas.vendorTokenSource(mount)
        if offer then
            local nativeName = C_Item and C_Item.GetItemInfo and C_Item.GetItemInfo(offer.item)
            return { item = offer.item, name = nativeName or offer.name,
                englishName = not nativeName and offer.englishName or nil, basis = "drop" }
        end
    end
    local choices = mount and atlas.mountRewardItems and atlas.mountRewardItems[mount.id]
    if not choices then return nil end
    local condition = location and location.condition or ""
    local faction = condition:find("Альянс", 1, true) and "Alliance"
        or condition:find("Орда", 1, true) and "Horde"
        or condition:find("Alliance", 1, true) and "Alliance"
        or condition:find("Horde", 1, true) and "Horde"
    if not faction and UnitFactionGroup then faction = UnitFactionGroup("player") end
    local npc = location and location.npc
    local function matchesNPC(choice)
        if npc then
            for _, id in ipairs(choice.npcs or {}) do if npc == id then return true end end
        end
        return false
    end
    local useNPC = false
    for _, choice in ipairs(choices) do if matchesNPC(choice) then useNPC = true; break end end
    local selected
    local directSource = ({ ["Квест"] = true, ["Достижение"] = true, ["Магазин"] = true,
        ["Акция"] = true, ["Торговая лавка"] = true })[mount.kind]
    for _, choice in ipairs(choices) do
        local eligible = useNPC and matchesNPC(choice) or not useNPC
            and (not choice.requiresAlliance or faction == "Alliance")
            and (not choice.requiresHorde or faction == "Horde")
        eligible = eligible and (not directSource or choice.rarityReward or includeTeachingItem)
        if eligible then
            if selected and selected.item ~= choice.item then return nil end
            selected = choice
        end
    end
    if not selected then return nil end
    local nativeName = C_Item and C_Item.GetItemInfo and C_Item.GetItemInfo(selected.item)
    local basis = includeTeachingItem and (directSource or mount.covenantSourceOnly)
        and not selected.rarityReward and "teaching" or "drop"
    return { item = selected.item, name = nativeName or selected.name,
        englishName = not nativeName and selected.englishName or nil, basis = basis }
end

